{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "budget_h2",
        "budget_text",
        "qualifying_h2",
        "qualifying_options_stack",
        "non_qualifying_h2",
        "non_qualifying_stack",
        "comparison_h2",
        "comparison_table",
        "recommendation_h2",
        "recommendation_media_stack",
        "recommendation_text_1",
        "recommendation_text_2",
        "actions_h2",
        "actions_stack",
        "sources_h2",
        "sources_stack"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Tokyo Corporate Retreat Hotel Evaluation",
        "variant": "h1"
      },
      "children": []
    },
    "budget_h2": {
      "type": "Text",
      "props": {
        "text": "Budget & Criteria Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "budget_text": {
      "type": "Text",
      "props": {
        "text": "Your requirement is for 5 rooms for 4 nights (20 total room nights) with a total budget of 800,000 JPY. This allows for a maximum of 40,000 JPY per room per night."
      },
      "children": []
    },
    "qualifying_h2": {
      "type": "Text",
      "props": {
        "text": "Qualifying Options",
        "variant": "h2"
      },
      "children": []
    },
    "qualifying_options_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "odakyu_card",
        "keio_card"
      ]
    },
    "odakyu_card": {
      "type": "Card",
      "props": {},
      "children": [
        "odakyu_title_stack",
        "odakyu_cost",
        "odakyu_criteria"
      ]
    },
    "odakyu_title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "odakyu_title",
        "odakyu_chip"
      ]
    },
    "odakyu_title": {
      "type": "Text",
      "props": {
        "text": "Odakyu Hotel Century Southern Tower",
        "variant": "h3"
      },
      "children": []
    },
    "odakyu_chip": {
      "type": "Text",
      "props": {
        "text": "Best Fit",
        "variant": "chip"
      },
      "children": []
    },
    "odakyu_cost": {
      "type": "Text",
      "props": {
        "text": "Total Cost: 38,000 x 20 = 760,000 JPY"
      },
      "children": []
    },
    "odakyu_criteria": {
      "type": "Text",
      "props": {
        "text": "Criteria: Within budget, 0.4km from station, 4.5 rating. MEETS ALL."
      },
      "children": []
    },
    "keio_card": {
      "type": "Card",
      "props": {},
      "children": [
        "keio_title",
        "keio_cost",
        "keio_criteria"
      ]
    },
    "keio_title": {
      "type": "Text",
      "props": {
        "text": "Keio Plaza Hotel",
        "variant": "h3"
      },
      "children": []
    },
    "keio_cost": {
      "type": "Text",
      "props": {
        "text": "Total Cost: 35,000 x 20 = 700,000 JPY"
      },
      "children": []
    },
    "keio_criteria": {
      "type": "Text",
      "props": {
        "text": "Criteria: Within budget, 0.5km from station, 4.4 rating. MEETS ALL."
      },
      "children": []
    },
    "non_qualifying_h2": {
      "type": "Text",
      "props": {
        "text": "Non-Qualifying Options",
        "variant": "h2"
      },
      "children": []
    },
    "non_qualifying_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "park_hyatt_text",
        "sunroute_text"
      ]
    },
    "park_hyatt_text": {
      "type": "Text",
      "props": {
        "text": "Park Hyatt Tokyo: 85,000 JPY/night exceeds the 40,000 JPY limit."
      },
      "children": []
    },
    "sunroute_text": {
      "type": "Text",
      "props": {
        "text": "Hotel Sunroute Plaza Shinjuku: 4.1 guest rating is below your 4.2 requirement."
      },
      "children": []
    },
    "comparison_h2": {
      "type": "Text",
      "props": {
        "text": "Hotel Comparison Table",
        "variant": "h2"
      },
      "children": []
    },
    "comparison_table": {
      "type": "Table",
      "props": {
        "columns": [
          { "key": "hotel", "label": "Hotel" },
          { "key": "distance", "label": "Distance to Station" },
          { "key": "rating", "label": "Guest Rating" },
          { "key": "price", "label": "Price per Night" }
        ],
        "rows": [
          { "hotel": "Odakyu Hotel Century", "distance": "0.4 km", "rating": "4.5", "price": "38,000 JPY" },
          { "hotel": "Keio Plaza Hotel", "distance": "0.5 km", "rating": "4.4", "price": "35,000 JPY" },
          { "hotel": "Hotel Sunroute Plaza", "distance": "0.3 km", "rating": "4.1", "price": "22,000 JPY" },
          { "hotel": "Park Hyatt Tokyo", "distance": "1.2 km", "rating": "4.8", "price": "85,000 JPY" }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "recommendation_h2": {
      "type": "Text",
      "props": {
        "text": "Final Recommendation: Odakyu Hotel Century Southern Tower",
        "variant": "h2"
      },
      "children": []
    },
    "recommendation_media_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "recommendation_image",
        "recommendation_icon"
      ]
    },
    "recommendation_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Shinjuku_Station_South_Exit.jpg/1200px-Shinjuku_Station_South_Exit.jpg"
      },
      "children": []
    },
    "recommendation_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/star.svg"
      },
      "children": []
    },
    "recommendation_text_1": {
      "type": "Text",
      "props": {
        "text": "This hotel provides the best balance of quality and location. It is closer to the station than Keio Plaza and offers the highest rating among qualifying options."
      },
      "children": []
    },
    "recommendation_text_2": {
      "type": "Text",
      "props": {
        "text": "The rooms are located on high floors (22nd and above), ensuring a quiet and professional environment for your retreat participants."
      },
      "children": []
    },
    "actions_h2": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "book_odakyu_button",
        "book_keio_button"
      ]
    },
    "book_odakyu_button": {
      "type": "Button",
      "props": {
        "label": "Book Odakyu Hotel"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.hotel-century.jp/en/"
          }
        }
      },
      "children": []
    },
    "book_keio_button": {
      "type": "Button",
      "props": {
        "label": "Book Keio Plaza"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.keioplaza.com/"
          }
        }
      },
      "children": []
    },
    "sources_h2": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "source_1",
        "source_2",
        "source_3",
        "source_4"
      ]
    },
    "source_1": {
      "type": "Text",
      "props": {
        "text": "Odakyu Hotel Century Southern Tower: https://www.hotel-century.jp/en/"
      },
      "children": []
    },
    "source_2": {
      "type": "Text",
      "props": {
        "text": "Keio Plaza Hotel: https://www.keioplaza.com/"
      },
      "children": []
    },
    "source_3": {
      "type": "Text",
      "props": {
        "text": "Hotel Sunroute Plaza Shinjuku: https://shinjuku.sunrouteplazashinjuku.jp/"
      },
      "children": []
    },
    "source_4": {
      "type": "Text",
      "props": {
        "text": "Park Hyatt Tokyo: https://www.hyatt.com/en-US/hotel/japan/park-hyatt-tokyo/tyoph"
      },
      "children": []
    }
  }
}
